witness.command:
set -u
W="${BENCH_WITNESS_DIR:-/tmp/bench-witness}"
C="${GOCOVERDIR:-/tmp/bench-witness/covdata}"
R=/build/go-git
M=github.com/go-git/go-git/v5/
command -v go >/dev/null 2>&1 || { echo "WITNESS-UNAVAILABLE go toolchain not on PATH"; exit 0; }
[ -r "$R/worktree_fs.go" ] || { echo "WITNESS-UNAVAILABLE audited source not readable at $R"; exit 0; }
mkdir -p "$W" || { echo "WITNESS-UNAVAILABLE cannot create witness dir $W"; exit 0; }
rm -f "$W/cover.txt"
go tool covdata textfmt -i="$C" -o="$W/cover.txt" 2>>"$W/witness.err" || echo "witness: covdata textfmt found no usable profile in $C" >>"$W/witness.err"
[ -s "$W/cover.txt" ] || exit 0
awk -v root="$R" -v mod="$M" '
function fname(l,   cp, recv, rest, op, br) {
  if (substr(l,1,6) == "func (") {
    cp = index(l, ")"); recv = substr(l, 7, cp-7); sub(/^[^ ]+ /, "", recv)
    rest = substr(l, cp+1); sub(/^ +/, "", rest)
  } else if (substr(l,1,5) == "func ") { recv = ""; rest = substr(l, 6) } else return ""
  op = index(rest, "("); br = index(rest, "[")
  if (br > 0 && br < op) op = br
  if (op < 2) return ""
  rest = substr(rest, 1, op-1)
  return (recv == "") ? rest : "(" recv ")." rest
}
NF == 3 {
  if ($3 + 0 == 0) next
  if (split($1, a, ":") != 2) next
  if (index(a[1], mod) != 1) next
  rel = substr(a[1], length(mod)+1)
  split(a[2], b, ","); split(b[1], c, ".")
  nb++; brel[nb] = rel; bln[nb] = c[1] + 0; want[rel] = 1
}
END {
  for (rel in want) {
    src = root "/" rel; close(src); i = 0; k = 0
    while ((getline l < src) > 0) { i++; if (substr(l,1,5) == "func ") { f = fname(l); if (f != "") { k++; dl[rel,k] = i; dn[rel,k] = f } } }
    close(src); nd[rel] = k
    if (k == 0) { print "WITNESS-UNAVAILABLE cannot map " rel " to declarations under " root; exit 0 }
  }
  for (j = 1; j <= nb; j++) {
    rel = brel[j]; best = 0
    for (k = 1; k <= nd[rel]; k++) if (dl[rel,k] <= bln[j] && dl[rel,k] > best) { best = dl[rel,k]; name = dn[rel,k] }
    if (best > 0) print "COVERED " rel "::" name
  }
}' "$W/cover.txt" | sort -u
